import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/unitary-method.svg",o="/img/restoration-method.svg",u=JSON.parse('{"title":"奥数精讲：归一与还原问题（从结果找原因）","description":"学习如何通过“归一”求出单一量解决比例问题，以及如何利用“倒推法”破解复杂的还原谜题。","frontmatter":{"title":"奥数精讲：归一与还原问题（从结果找原因）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["归一问题","还原问题","逆向思维"],"description":"学习如何通过“归一”求出单一量解决比例问题，以及如何利用“倒推法”破解复杂的还原谜题。"},"headers":[],"relativePath":"posts/primary-math-olympiad-restoration-unitary.md","filePath":"posts/primary-math-olympiad-restoration-unitary.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-restoration-unitary.md"};function l(e,a,i,c,h,d){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="归一与还原问题-逻辑的双向奔赴" tabindex="-1">归一与还原问题：逻辑的双向奔赴 <a class="header-anchor" href="#归一与还原问题-逻辑的双向奔赴" aria-label="Permalink to &quot;归一与还原问题：逻辑的双向奔赴&quot;">​</a></h1><p>在数学应用题中，有两类问题非常锻炼我们的逻辑：一类是需要先求出“一份是多少”的<strong>归一问题</strong>；另一类是知道最后结果，需要“倒着往回推”的<strong>还原问题</strong>。</p><hr><h2 id="一、-归一问题-先求-单一量" tabindex="-1">一、 归一问题：先求“单一量” <a class="header-anchor" href="#一、-归一问题-先求-单一量" aria-label="Permalink to &quot;一、 归一问题：先求“单一量”&quot;">​</a></h2><p>归一问题的核心思想是：在求出总量或数量之前，必须先求出一个单位的数量（单一量）。</p><h3 id="【示例-1】基础归一" tabindex="-1">【示例 1】基础归一 <a class="header-anchor" href="#【示例-1】基础归一" aria-label="Permalink to &quot;【示例 1】基础归一&quot;">​</a></h3><p><strong>题目：</strong> 小明买了 3 支钢笔花了 15 元。照这样计算，买 5 支同样的钢笔需要多少钱？</p><p><img src="'+p+'" alt="归一问题图解"></p><p><strong>解题步骤：</strong></p><ol><li><strong>归一（求一份）：</strong> 先求出 1 支钢笔的价格。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">15 \\div 3 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>（元）。</li><li><strong>扩缩（求多份）：</strong> 再求 5 支钢笔的价格。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>2</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">5 \\times 5 = 25</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span></span></span></span>（元）。 <strong>结论：</strong> 买 5 支钢笔需要 25 元。</li></ol><hr><h2 id="二、-还原问题-倒着走的侦探" tabindex="-1">二、 还原问题：倒着走的侦探 <a class="header-anchor" href="#二、-还原问题-倒着走的侦探" aria-label="Permalink to &quot;二、 还原问题：倒着走的侦探&quot;">​</a></h2><p>还原问题（也叫逆推问题）通常给出一系列运算过程和最终结果，要求求出初始值。</p><h3 id="【关键秘籍-逆运算】" tabindex="-1">【关键秘籍：逆运算】 <a class="header-anchor" href="#【关键秘籍-逆运算】" aria-label="Permalink to &quot;【关键秘籍：逆运算】&quot;">​</a></h3><ul><li>加法的逆运算是 <strong>减法</strong></li><li>减法的逆运算是 <strong>加法</strong></li><li>乘法的逆运算是 <strong>除法</strong></li><li>除法的逆运算是 <strong>乘法</strong></li></ul><h3 id="【示例-2】神奇的数字" tabindex="-1">【示例 2】神奇的数字 <a class="header-anchor" href="#【示例-2】神奇的数字" aria-label="Permalink to &quot;【示例 2】神奇的数字&quot;">​</a></h3><p><strong>题目：</strong> 一个数乘以 2，再加 5，结果是 15。请问这个数是多少？</p><p><img src="'+o+'" alt="还原问题步骤图"></p><p><strong>解题步骤：</strong></p><ol><li><strong>最后一步是“加 5”：</strong> 我们逆推回去，就要“减 5”。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">15 - 5 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。</li><li><strong>前一步是“乘以 2”：</strong> 我们逆推回去，就要“除以 2”。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">10 \\div 2 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>。 <strong>结论：</strong> 初始数字是 5。</li></ol><hr><h2 id="三、-引导性思考-如何解决复杂的还原问题" tabindex="-1">三、 引导性思考：如何解决复杂的还原问题？ <a class="header-anchor" href="#三、-引导性思考-如何解决复杂的还原问题" aria-label="Permalink to &quot;三、 引导性思考：如何解决复杂的还原问题？&quot;">​</a></h2><p>解决还原问题时，建议画一个“流程图”：</p><ol><li><strong>正向画图：</strong> 用方框和箭头表示题目中的每一步变化。</li><li><strong>逆向标号：</strong> 从结果开始，每一步都换成相反的运算。</li><li><strong>一步步算：</strong> 只要运算不粗心，复杂的问题也能迎刃而解。</li></ol><hr><h2 id="四、-引申思考-正归一与反归一" tabindex="-1">四、 引申思考：正归一与反归一 <a class="header-anchor" href="#四、-引申思考-正归一与反归一" aria-label="Permalink to &quot;四、 引申思考：正归一与反归一&quot;">​</a></h2><ul><li><strong>正归一：</strong> 先求一份是多少，再求总量（如示例 1）。</li><li><strong>反归一：</strong> 先求一份是多少，再求总量能分成多少份。 <ul><li><em>例如：15元买3支笔，那么30元能买几支？</em> (<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>0</mn><mo>÷</mo><mo>(</mo><mn>1</mn><mn>5</mn><mo>÷</mo><mn>3</mn><mo>)</mo><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">30 \\div (15 \\div 3) = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>支)</li></ul></li></ul><hr><h2 id="五、-举一反三-实战练习" tabindex="-1">五、 举一反三：实战练习 <a class="header-anchor" href="#五、-举一反三-实战练习" aria-label="Permalink to &quot;五、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习（归一）：</strong> 5 台机器 2 小时可以生产 200 个零件。照这样计算，8 台同样的机器 1 小时可以生产多少个零件？ <em>提示：先求 1 台机器 1 小时生产多少个（单一量）。</em></p></li><li><p><strong>进阶练习（还原）：</strong> 某人去逛街，先花掉了一半的钱，又花了 10 元，最后剩下 40 元。请问他出门时带了多少钱？ <em>提示：最后剩下 40，逆推：先加 10，再乘以 2。</em></p></li><li><p><strong>挑战练习（综合）：</strong> 某数加上 6，除以 3，再减去 2，乘以 10，最后结果是 40。求这个数。</p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>单一量：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">200 \\div 5 \\div 2 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> (个/台/小时)。结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>8</mn><mo>×</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 8 \\times 1 = 160</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span> 个。</li><li>逆推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>4</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mo>)</mo><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">(40 + 10) \\times 2 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span> 元。</li><li>逆推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>4</mn><mn>0</mn><mo>÷</mo><mn>1</mn><mn>0</mn><mo>+</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>3</mn><mo>−</mo><mn>6</mn><mo>=</mo><mo>(</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>3</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>8</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">(40 \\div 10 + 2) \\times 3 - 6 = (4 + 2) \\times 3 - 6 = 18 - 6 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>。</li></ol>',33)])])}const x=s(r,[["render",l]]);export{u as __pageData,x as default};
